1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Derives an owner's canonical region ('locality'), preferring the postcode over the city.
5	 * Both the postcode-range and city-to-region tables live on {@link Region}; this resolver
6	 * looks the region up by postcode first and only falls back to the city when the postcode is
7	 * absent or in no known range, turning the resolved region into the {@code locality} string an
8	 * owner is mapped with, using {@link #UNKNOWN} when neither postcode nor city maps to a known
9	 * region. Kept out of {@link OwnerMapper} so MapStruct does not mistake it for an implicit
10	 * {@code String -> String} property mapping method.
11	 */
12	public final class LocalityResolver {
13	
14	    /** Locality returned for a city that belongs to no known {@link Region}. */
15	    public static final String UNKNOWN = "UNKNOWN";
16	
17	    private LocalityResolver() {
18	    }
19	
20	    /**
21	     * Returns the canonical region for the given owner, preferring the postcode range
22	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) over the city-to-region table
23	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). Falls back to the city only when the
24	     * postcode is absent or in no known range, and returns "UNKNOWN" when neither maps to a
25	     * known region (including a {@code null} city and postcode).
26	     */
27	    public static String deriveLocality(String city, String postcode) {
28	        Region region = Region.forPostcode(postcode);
29	        if (region == null) {
30	            region = Region.forCity(city);
31	        }
32	        return region == null ? UNKNOWN : region.name();
33	    }
34	}
