1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "checkDigit",
26	        expression = "java(org.springframework.samples.petclinic.mapper.CheckDigitResolver.deriveCheckDigit(owner.getCustomerCode()))")
27	    @Mapping(target = "membershipNumber",
28	        expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
29	    @Mapping(target = "membershipLevel",
30	        expression = "java(org.springframework.samples.petclinic.mapper.MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()))")
31	    @Mapping(target = "locality",
32	        expression = "java(org.springframework.samples.petclinic.mapper.LocalityResolver.deriveLocality(owner.getCity(), owner.getPostcode()))")
33	    @Mapping(target = "bulkSignupWarning",
34	        expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
35	    @Mapping(target = "contactPreference",
36	        expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
37	    @Mapping(target = "sharesHousehold", ignore = true)
38	    @Mapping(target = "identityKey", ignore = true)
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    Owner toOwner(OwnerDto ownerDto);
42	
43	    @Mapping(target = "id", ignore = true)
44	    @Mapping(target = "pets", ignore = true)
45	    Owner toOwner(OwnerFieldsDto ownerDto);
46	
47	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
48	
49	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
50	
51	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
52	        OwnerPageDto ownerPageDto = new OwnerPageDto();
53	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
54	        ownerPageDto.setPage(ownerPage.getNumber());
55	        ownerPageDto.setSize(ownerPage.getSize());
56	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
57	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
58	        return ownerPageDto;
59	    }
60	}
