67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
76	    private static final int MAX_OWNERS_PER_CITY = 50;
77	
78	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
79	    private static final int MAX_OWNERS_PER_DAY = 100;
80	
81	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
82	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    private final TelephoneNormalizer telephoneNormalizer;
93	
94	    private final AddressNormalizer addressNormalizer;
95	
96	    private final EmailNormalizer emailNormalizer;
97	
98	    private final IdentityKeyResolver identityKeyResolver;
99	
100	    public OwnerRestControllerV1(ClinicService clinicService,
101	                                 OwnerMapper ownerMapper,
102	                                 PetMapper petMapper,
103	                                 VisitMapper visitMapper,
104	                                 TelephoneNormalizer telephoneNormalizer,
105	                                 AddressNormalizer addressNormalizer,
106	                                 EmailNormalizer emailNormalizer,
107	                                 IdentityKeyResolver identityKeyResolver) {
108	        this.clinicService = clinicService;
109	        this.ownerMapper = ownerMapper;
110	        this.petMapper = petMapper;
111	        this.visitMapper = visitMapper;
112	        this.telephoneNormalizer = telephoneNormalizer;
113	        this.addressNormalizer = addressNormalizer;
114	        this.emailNormalizer = emailNormalizer;
115	        this.identityKeyResolver = identityKeyResolver;
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
121	        Collection<Owner> owners;
122	        if (lastName != null) {
123	            owners = this.clinicService.findOwnerByLastName(lastName);
124	        } else {
125	            owners = this.clinicService.findAllOwners();
126	        }
127	        if (owners.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        owners.forEach(this::populateHouseholdMemberCount);
131	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
132	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        populateHouseholdMemberCount(owner);
143	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    /**
147	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
148	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
149	     * by the mapper alone.
150	     *
151	     * @param owner the owner to map
152	     * @return the owner DTO carrying its identity key
153	     */
154	    private OwnerDto toOwnerDto(Owner owner) {
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
157	        return ownerDto;
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Transactional
162	    @Override
163	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
164	        normalizeAndValidate(ownerFieldsDto);
165	        HttpHeaders headers = new HttpHeaders();
166	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
167	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
168	        owner.setNamesakeCount(countNamesakes(owner));
169	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
170	        assignHouseholdId(owner, ownerFieldsDto);
171	        requireUniqueIdentity(owner);
172	        this.clinicService.saveOwner(owner);
173	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
174	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
175	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
176	        populateHouseholdMemberCount(owner);
177	        OwnerDto ownerDto = toOwnerDto(owner);
178	        headers.setLocation(UriComponentsBuilder.newInstance()
179	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
180	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
181	    }
182	
183	    /**
184	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
185	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
186	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
187	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
188	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
189	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
190	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
191	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
192	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
193	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
194	     * assigned (see {@link #requireUniqueIdentity}).
195	     *
196	     * @param ownerFieldsDto the incoming owner payload, mutated in place
197	     * @throws MissingOwnerFieldsException if any required field is missing or blank
198	     */
199	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
200	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
201	        validateRequiredFields(ownerFieldsDto);
202	        validatePostcode(ownerFieldsDto);
203	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
204	        ownerFieldsDto.setTelephone(telephone);
205	        requireCityHasCapacity(ownerFieldsDto.getCity());
206	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
207	        ownerFieldsDto.setRegistrationDate(registrationDate);
208	        requireDailyLimitNotReached(registrationDate);
209	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
210	        ownerFieldsDto.setEmail(email);
211	    }
212	
213	    /**
214	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
215	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
216	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
217	     *
218	     * @param ownerFieldsDto the incoming owner payload
219	     * @return the effective registration date rolled forward onto a business day
220	     */
221	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
222	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
223	        if (effective == null) {
224	            effective = LocalDate.now();
225	        }
226	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
227	            effective = effective.plusDays(1);
228	        }
229	        return effective;
230	    }
231	
232	    /**
233	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
234	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
235	     * further owner may be created for that day.
236	     *
237	     * @param registrationDate the adjusted business-day registration date of the owner being created
238	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
239	     */
240	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
241	        long createdThatDay = this.clinicService.findAllOwners().stream()
242	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
243	            .count();
244	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
245	            throw new DailyOwnerLimitExceededException(
246	                "the maximum number of owners for today has already been reached");
247	        }
248	    }
249	
250	    /**
251	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
252	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
253	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
254	     * reflects only owners that predate it.
255	     *
256	     * @param registrationDate the adjusted business-day registration date of the owner being created
257	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
258	     */
259	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
260	        long createdThatDay = this.clinicService.findAllOwners().stream()
261	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
262	            .count();
263	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
264	    }
265	
266	    /**
267	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
268	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
269	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
270	     * city (e.g. {@code LON-SMI-0007}).
271	     *
272	     * @param city     the owner's city
273	     * @param lastName the owner's last name
274	     * @return the generated customer code
275	     */
276	    private String generateCustomerCode(String city, String lastName) {
277	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
278	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
279	        int sequence = (int) this.clinicService.findAllOwners().stream()
280	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
281	            .count() + 1;
282	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
283	    }
284	
285	    /**
286	     * Counts how many existing owners already share the given owner's first and last name, compared
287	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
288	     * create; it is zero when the owner's name is unique.
289	     *
290	     * @param owner the newly mapped owner about to be saved
291	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
292	     */
293	    private int countNamesakes(Owner owner) {
294	        String firstName = owner.getFirstName();
295	        String lastName = owner.getLastName();
296	        return (int) this.clinicService.findAllOwners().stream()
297	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
298	                && lastName.equalsIgnoreCase(existing.getLastName()))
299	            .count();
300	    }
301	
302	    /**
303	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
304	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
305	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
306	     *
307	     * @param ownerFieldsDto the owner payload to validate
308	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
309	     */
310	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
311	        List<String> missingFields = new ArrayList<>();
312	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
313	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
314	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
315	        requireText(missingFields, "city", ownerFieldsDto.getCity());
316	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
317	        if (!missingFields.isEmpty()) {
318	            throw new MissingOwnerFieldsException(missingFields);
319	        }
320	    }
321	
322	    private void requireText(List<String> missingFields, String fieldName, String value) {
323	        if (value == null || value.isBlank()) {
324	            missingFields.add(fieldName);
325	        }
326	    }
327	
328	    /**
329	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
330	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
331	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
332	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
333	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
334	     *
335	     * @param ownerFieldsDto the incoming owner payload
336	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
337	     */
338	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
339	        String postcode = ownerFieldsDto.getPostcode();
340	        if (postcode == null) {
341	            return;
342	        }
343	        Region region = Region.forCity(ownerFieldsDto.getCity());
344	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
345	            throw new InvalidPostcodeException(
346	                "postcode " + postcode + " is not valid for the city's region " + region.name());
347	        }
348	    }
349	
350	    /**
351	     * Rejects creating an owner whose whole derived {@code identityKey} (see
352	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner. This is the single, consolidated
353	     * duplicate check: the former separate telephone, email and household rules are all expressed through this one key,
354	     * so an owner is a duplicate only when its normalized telephone, email and {@code householdId} all match another
355	     * owner's. It runs after the household id has been assigned, so the key reflects the household the owner belongs to.
356	     *
357	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
358	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
359	     */
360	    private void requireUniqueIdentity(Owner owner) {
361	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
362	        boolean inUse = this.clinicService.findAllOwners().stream()
363	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
364	        if (inUse) {
365	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
366	        }
367	    }
368	
369	    /**
370	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
371	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
372	     *
373	     * @param city the city of the owner being created
374	     * @throws OwnerCityFullException if the city already contains 50 or more owners
375	     */
376	    private void requireCityHasCapacity(String city) {
377	        long cityOwners = this.clinicService.findAllOwners().stream()
378	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
379	            .count();
380	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
381	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
382	        }
383	    }
384	
385	    /**
386	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
387	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
388	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
389	     * incidental formatting differences and abbreviation variants do not affect membership.
390	     *
391	     * @param ownerFieldsDto the incoming owner payload
392	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
393	     *         them; empty when none match
394	     */
395	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
396	        String lastName = identityKeyResolver.collapseWhitespace(ownerFieldsDto.getLastName());
397	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
398	        return this.clinicService.findAllOwners().stream()
399	            .filter(existing -> identityKeyResolver.collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
400	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
401	            .toList();
402	    }
403	
404	    /**
405	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
406	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
407	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
408	     * identifier is derived deterministically from the household's last name and address (see
409	     * {@link IdentityKeyResolver#deriveHouseholdId}), so every member of the same household resolves to the same stable
410	     * value regardless of creation order. Existing members that predate the feature and still lack the identifier are
411	     * backfilled (see {@link #backfillHouseholdMembers}) so the whole household shares it.
412	     *
413	     * @param owner          the newly mapped owner about to be saved
414	     * @param ownerFieldsDto the incoming owner payload
415	     */
416	    private void assignHouseholdId(Owner owner, OwnerFieldsDto ownerFieldsDto) {
417	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
418	            return;
419	        }
420	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
421	        if (members.isEmpty()) {
422	            return;
423	        }
424	        String householdId =
425	            identityKeyResolver.deriveHouseholdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
426	        owner.setHouseholdId(householdId);
427	        backfillHouseholdMembers(householdId, members);
428	    }
429	
430	    /**
431	     * Stamps the shared {@code householdId} onto the existing members of a household that do not already carry it,
432	     * persisting each one that changes. Members that predate the feature (and so still lack the identifier) are brought
433	     * into line so the whole household shares the single value; members that already carry it are left untouched.
434	     *
435	     * @param householdId the shared household identifier
436	     * @param members     the existing owners in the household
437	     */
438	    private void backfillHouseholdMembers(String householdId, List<Owner> members) {
439	        for (Owner member : members) {
440	            if (!householdId.equals(member.getHouseholdId())) {
441	                member.setHouseholdId(householdId);
442	                this.clinicService.saveOwner(member);
443	            }
444	        }
445	    }
446	
447	    /**
448	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
449	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
450	     * household is counted as a household of one.
451	     *
452	     * @param owner the owner whose household size should be resolved
453	     */
454	    private void populateHouseholdMemberCount(Owner owner) {
455	        String householdId = owner.getHouseholdId();
456	        if (householdId == null) {
457	            owner.setHouseholdMemberCount(1);
458	            return;
459	        }
460	        long members = this.clinicService.findAllOwners().stream()
461	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
462	            .count();
463	        owner.setHouseholdMemberCount((int) members);
464	    }
465	
466	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
467	    @Override
468	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
469	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
470	        if (currentOwner == null) {
471	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
472	        }
473	        validatePostcode(ownerFieldsDto);
474	        currentOwner.setAddress(ownerFieldsDto.getAddress());
475	        currentOwner.setCity(ownerFieldsDto.getCity());
476	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
477	        currentOwner.setLastName(ownerFieldsDto.getLastName());
478	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
479	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
480	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
481	        this.clinicService.saveOwner(currentOwner);
482	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
483	    }
484	
485	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
486	    @Transactional
487	    @Override
488	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
489	        Owner owner = this.clinicService.findOwnerById(ownerId);
490	        if (owner == null) {
491	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
492	        }
493	        this.clinicService.deleteOwner(owner);
494	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
495	    }
496	
497	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
498	    @Override
499	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
500	        Owner owner = this.clinicService.findOwnerById(ownerId);
501	        if (owner == null) {
502	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
503	        }
504	        HttpHeaders headers = new HttpHeaders();
505	        Pet pet = petMapper.toPet(petFieldsDto);
506	        owner.setId(ownerId);
507	        pet.setOwner(owner);
508	        pet.getType().setName(null);
509	        this.clinicService.savePet(pet);
510	        PetDto petDto = petMapper.toPetDto(pet);
511	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
512	            .buildAndExpand(pet.getId()).toUri());
513	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
514	    }
515	
516	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
517	    @Override
518	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
519	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
520	        if (currentOwner != null) {
521	            Pet currentPet = this.clinicService.findPetById(petId);
522	            if (currentPet != null) {
523	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
524	                currentPet.setName(petFieldsDto.getName());
525	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
526	                this.clinicService.savePet(currentPet);
527	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
528	            }
529	        }
530	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
531	    }
532	
533	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
534	    @Override
535	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
536	        HttpHeaders headers = new HttpHeaders();
537	        Visit visit = visitMapper.toVisit(visitFieldsDto);
538	        Pet pet = new Pet();
539	        pet.setId(petId);
540	        visit.setPet(pet);
541	        this.clinicService.saveVisit(visit);
542	        VisitDto visitDto = visitMapper.toVisitDto(visit);
543	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
544	            .buildAndExpand(visit.getId()).toUri());
545	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
546	    }
547	
548	
549	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
550	    @Override
551	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
552	        Owner owner = this.clinicService.findOwnerById(ownerId);
553	        if (owner != null) {
554	            Pet pet = owner.getPet(petId);
555	            if (pet != null) {
556	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
557	            }
558	        }
559	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
560	    }
561	}
