62	        for (String token : collapsed.split(" ")) {
63	            if (result.length() > 0) {
64	                result.append(' ');
65	            }
66	            result.append(ABBREVIATIONS.getOrDefault(token, token));
67	        }
68	        return result.toString();
69	    }
